import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type FlightBoardProps = Record<string, any>;

const CHARS = " ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-:.";
const getChar = (index: number) => CHARS[((index % CHARS.length) + CHARS.length) % CHARS.length];

const PlaneIcon: React.FC<{ style?: React.CSSProperties }> = ({ style }) => (
  <svg 
    viewBox="0 0 24 24" 
    width="100%" 
    height="100%" 
    fill="currentColor"
    style={{ ...style, transition: 'none' }}
  >
    <path d="M21 16v-2l-8-5V3.5c0-.83-.67-1.5-1.5-1.5S10 2.67 10 3.5V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5l8 2.5z" />
  </svg>
);

const HalfFlap: React.FC<{
  char: string;
  type: 'top' | 'bottom';
  rotateX: number;
  zIndex: number;
  flapWidth: number;
  flapHeight: number;
  accentColor: string;
}> = ({ char, type, rotateX, zIndex, flapWidth, flapHeight, accentColor }) => {
  return (
    <div style={{
      position: 'absolute',
      left: 0,
      width: flapWidth,
      height: flapHeight / 2,
      overflow: 'hidden',
      top: type === 'top' ? 0 : flapHeight / 2,
      transformOrigin: type === 'top' ? 'bottom' : 'top',
      transform: `rotateX(${rotateX}deg)`,
      zIndex,
      backgroundColor: '#151515',
      backgroundImage: type === 'top' 
        ? 'linear-gradient(to bottom, #262626 0%, #111111 100%)' 
        : 'linear-gradient(to bottom, #111111 0%, #262626 100%)',
      backfaceVisibility: 'hidden',
      borderBottom: type === 'top' ? '1px solid #000' : 'none',
      borderTop: type === 'bottom' ? '1px solid #000' : 'none',
      borderRadius: type === 'top' ? '4px 4px 0 0' : '0 0 4px 4px',
      boxShadow: 'inset 0 0 2px rgba(0,0,0,0.8)',
      transition: 'none',
    }}>
      <div style={{
        position: 'absolute',
        width: '100%',
        height: flapHeight,
        top: type === 'top' ? 0 : -flapHeight / 2,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: accentColor,
        fontSize: flapHeight * 0.75,
        fontWeight: 600,
        transition: 'none',
      }}>
        {char}
      </div>
      
      <div style={{
        position: 'absolute',
        top: 0, left: 0, right: 0, bottom: 0,
        background: type === 'top' 
          ? 'linear-gradient(to bottom, rgba(255,255,255,0.08) 0%, rgba(255,255,255,0) 100%)' 
          : 'none',
        pointerEvents: 'none',
      }} />
    </div>
  );
};

const SplitFlap: React.FC<{
  initialChar: string;
  targetChar: string;
  startFrame: number;
  framesPerFlip: number;
  flapWidth: number;
  flapHeight: number;
  accentColor: string;
}> = ({ initialChar, targetChar, startFrame, framesPerFlip, flapWidth, flapHeight, accentColor }) => {
  const frame = useCurrentFrame();

  const initialIndex = Math.max(0, CHARS.indexOf(initialChar.toUpperCase()));
  const targetIndex = Math.max(0, CHARS.indexOf(targetChar.toUpperCase()));

  const MIN_FLIPS = 15;
  let totalFlips = (targetIndex - initialIndex + CHARS.length) % CHARS.length;
  while (totalFlips < MIN_FLIPS) {
    totalFlips += CHARS.length;
  }

  const duration = totalFlips * framesPerFlip;
  const endFrame = startFrame + duration;

  const isFlipping = frame >= startFrame && frame < endFrame;
  const isFinished = frame >= endFrame;

  let currentFlip = 0;
  let flipProgress = 0;

  if (frame < startFrame) {
    currentFlip = 0;
    flipProgress = 0;
  } else if (frame >= endFrame) {
    currentFlip = totalFlips;
    flipProgress = 0;
  } else {
    const framesElapsed = frame - startFrame;
    currentFlip = Math.floor(framesElapsed / framesPerFlip);
    flipProgress = (framesElapsed % framesPerFlip) / framesPerFlip;
  }

  const char1 = getChar(initialIndex + currentFlip);
  const char2 = getChar(initialIndex + currentFlip + 1);

  const displayChar1 = isFinished ? getChar(initialIndex + totalFlips) : char1;
  const displayChar2 = isFinished ? displayChar1 : char2;

  const flipAngle = flipProgress * -180;

  return (
    <div style={{
      position: 'relative',
      width: flapWidth,
      height: flapHeight,
      perspective: '800px',
      transition: 'none',
    }}>
      <HalfFlap char={displayChar2} type="top" rotateX={0} zIndex={1} flapWidth={flapWidth} flapHeight={flapHeight} accentColor={accentColor} />
      <HalfFlap char={displayChar1} type="bottom" rotateX={0} zIndex={1} flapWidth={flapWidth} flapHeight={flapHeight} accentColor={accentColor} />
      
      {isFlipping && (
        <>
          <HalfFlap char={displayChar1} type="top" rotateX={flipAngle} zIndex={2} flapWidth={flapWidth} flapHeight={flapHeight} accentColor={accentColor} />
          <HalfFlap char={displayChar2} type="bottom" rotateX={flipAngle + 180} zIndex={2} flapWidth={flapWidth} flapHeight={flapHeight} accentColor={accentColor} />
        </>
      )}
      
      <div style={{
        position: 'absolute',
        top: '50%',
        left: 0,
        width: '100%',
        height: '2px',
        backgroundColor: '#050505',
        transform: 'translateY(-50%)',
        zIndex: 3,
        boxShadow: '0 1px 1px rgba(255,255,255,0.05)',
      }} />
    </div>
  );
};

const FlightBoard: React.FC<FlightBoardProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "DEPARTURES",
  columnHeaders = ["TIME", "DESTINATION", "FLIGHT"],
  initialRows = [
    "10:30 CANCUN        AA12",
    "11:15 MIAMI         DL45",
    "12:00 CABO          UA78"
  ],
  targetRows = [
    "BEFORE TAKEOFF          ",
    "      SIGN AT STATION   ",
    "                        "
  ],
  accentColor = "#ffffff",
}) => {
  useFontLoader(["Oswald"]);
  
  const { width, height, durationInFrames } = useVideoConfig();
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const FLAPS_PER_ROW = 24;
  
  const processRow = (row: string) => {
    return row.padEnd(FLAPS_PER_ROW, ' ').substring(0, FLAPS_PER_ROW).split('');
  };

  const safeInitialRows = initialRows.map(processRow);
  const safeTargetRows = targetRows.map(processRow);

  const availableWidth = width * 0.96;
  const flapGap = availableWidth * 0.004;
  const flapWidth = (availableWidth - (FLAPS_PER_ROW - 1) * flapGap) / FLAPS_PER_ROW;
  const flapHeight = flapWidth * 1.45;

  const globalStartDelay = durationInFrames * 0.05;
  const globalEndFrame = durationInFrames * 0.9;
  const staggerWindow = (globalEndFrame - globalStartDelay) * 0.3;
  const flipWindow = (globalEndFrame - globalStartDelay) * 0.7;
  const framesPerFlip = flipWindow / 55;

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      fontFamily: '"Oswald", sans-serif',
      display: 'flex',
      flexDirection: 'column',
      paddingTop: height * 0.12,
      paddingLeft: width * 0.02,
      paddingRight: width * 0.02,
    }}>
      
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        padding: `0 ${width * 0.04}px`,
        marginBottom: height * 0.03,
        color: accentColor,
      }}>
        <div style={{ width: width * 0.04, height: width * 0.04 }}>
          <PlaneIcon style={{ transform: 'rotate(45deg)' }} />
        </div>
        <div style={{
          fontSize: width * 0.08,
          fontWeight: 700,
          letterSpacing: '0.08em',
        }}>
          {title}
        </div>
        <div style={{ width: width * 0.04, height: width * 0.04 }}>
          <PlaneIcon style={{ transform: 'rotate(-45deg)' }} />
        </div>
      </div>

      <div style={{
        width: '100%',
        height: 2,
        backgroundColor: '#333',
        marginBottom: height * 0.04,
      }} />

      <div style={{
        display: 'flex',
        flexDirection: 'row',
        padding: `0 ${width * 0.02}px`,
        marginBottom: height * 0.03,
        fontSize: width * 0.022,
        fontWeight: 600,
        color: '#aaaaaa',
        letterSpacing: '0.05em',
      }}>
        <div style={{ flex: 1, textAlign: 'left' }}>{columnHeaders[0]}</div>
        <div style={{ flex: 2, textAlign: 'center' }}>{columnHeaders[1]}</div>
        <div style={{ flex: 1, textAlign: 'right' }}>{columnHeaders[2]}</div>
      </div>

      <div style={{
        display: 'flex',
        flexDirection: 'column',
        gap: flapHeight * 0.15,
        alignItems: 'center',
      }}>
        {safeInitialRows.map((initialChars, rowIndex) => {
          const targetChars = safeTargetRows[rowIndex] || processRow("");
          const rowFraction = rowIndex / Math.max(1, safeInitialRows.length - 1);

          return (
            <div key={rowIndex} style={{ display: 'flex', gap: flapGap }}>
              {initialChars.map((char, colIndex) => {
                const colFraction = colIndex / Math.max(1, FLAPS_PER_ROW - 1);
                const startFrame = globalStartDelay + staggerWindow * (rowFraction * 0.6 + colFraction * 0.4);

                return (
                  <SplitFlap 
                    key={`${rowIndex}-${colIndex}`}
                    initialChar={char}
                    targetChar={targetChars[colIndex]}
                    startFrame={startFrame}
                    framesPerFlip={framesPerFlip}
                    flapWidth={flapWidth}
                    flapHeight={flapHeight}
                    accentColor={accentColor}
                  />
                );
              })}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default FlightBoard;